import type { CSSProperties, Ref } from "react";

/**
 * The footer's giant spacegear wordmark: concept B "Shift", drawn (no font), one element per glyph.
 * Generated by the identity kit's tools from the same geometry as the masters in docs/brand/svg/; change
 * these paths only together with the masters.
 *
 * - Sized like text: it follows the font-size of its context (1em = 183.150 units; the x-height is
 *   0.546em, Inter's own, so the footer's existing font-size clamps keep today's size).
 * - Motion-ready, static by default: every glyph is a `<span data-letter class="fx-letter glyph-…">` with
 *   `--i` (its index) holding its own inline SVG, so the motion work's rise and cursor lean
 *   (`.fx-letter` translate/transform, staggered by `--i`) apply per glyph. Nothing moves here; under
 *   `prefers-reduced-motion: reduce` the motion work must leave the glyphs at rest.
 * - Accessible: the visible glyphs are `aria-hidden`; a `.sr-only` "spacegear" gives the name.
 * - Server-safe: no hooks and no client-only code. `ref` is a plain prop (React 19) for a client wrapper.
 */

type WordmarkProps = {
  /** Show the drawn ™ (default true: the footer is the one place it is legible). */
  tm?: boolean;
  className?: string;
  ref?: Ref<HTMLParagraphElement>;
};

/** Units per em: x-height 100 units = 0.546em. */
const EM = 183.150;
/** Every glyph box spans the same band (x-height top − 10 to descender + 10), so baselines line up. */
const BAND = 156.0;

/** [id, character, cell width, path] — cells abut, so spacing and kerning live inside them. */
export const WORDMARK_GLYPHS = [
  ["glyph-s", "s", 99.16, "M92.16 10L92.16 30L34.74 30A9.74 9.74 0 0 0 25 39.74L25 39.76A9.74 9.74 0 0 0 34.74 49.5L65.42 49.5A29.74 29.74 0 0 1 95.16 79.24L95.16 80.26A29.74 29.74 0 0 1 65.42 110L8 110L8 90L65.42 90A9.74 9.74 0 0 0 75.16 80.26L75.16 79.24A9.74 9.74 0 0 0 65.42 69.5L34.74 69.5A29.74 29.74 0 0 1 5 39.76L5 39.74A29.74 29.74 0 0 1 34.74 10L92.16 10Z"],
  ["glyph-p", "p", 110.0, "M48 10L66 10A40 40 0 0 1 106 50L106 70A40 40 0 0 1 66 110L48 110A40 40 0 0 1 8 70L8 50A40 40 0 0 1 48 10ZM48 30A20 20 0 0 0 28 50L28 70A20 20 0 0 0 48 90L66 90A20 20 0 0 0 86 70L86 50A20 20 0 0 0 66 30L48 30ZM8 10L28 10L28 146L8 146L8 10Z"],
  ["glyph-a1", "a", 110.0, "M45 10L63 10A40 40 0 0 1 103 50L103 70A40 40 0 0 1 63 110L45 110A40 40 0 0 1 5 70L5 50A40 40 0 0 1 45 10ZM45 30A20 20 0 0 0 25 50L25 70A20 20 0 0 0 45 90L63 90A20 20 0 0 0 83 70L83 50A20 20 0 0 0 63 30L45 30ZM83 10L103 10L103 110L83 110L83 10Z"],
  ["glyph-c", "c", 98.12, "M94.12 10L94.12 30L45 30A20 20 0 0 0 25 50L25 70A20 20 0 0 0 45 90L94.12 90L94.12 110L45 110A40 40 0 0 1 5 70L5 50A40 40 0 0 1 45 10L94.12 10Z"],
  ["glyph-e1", "e", 106.0, "M103 59L83 59L83 50A20 20 0 0 0 63 30L45 30A20 20 0 0 0 25 50L25 70A20 20 0 0 0 45 90L100 90L100 110L45 110A40 40 0 0 1 5 70L5 50A40 40 0 0 1 45 10L63 10A40 40 0 0 1 103 50L103 59ZM15 50L103 50L103 68L15 68L15 50Z"],
  ["glyph-g1", "g", 110.0, "M45 10L63 10A40 40 0 0 1 103 50L103 70A40 40 0 0 1 63 110L45 110A40 40 0 0 1 5 70L5 50A40 40 0 0 1 45 10ZM45 30A20 20 0 0 0 25 50L25 70A20 20 0 0 0 45 90L63 90A20 20 0 0 0 83 70L83 50A20 20 0 0 0 63 30L45 30ZM83 10L103 10L103 109A37 37 0 0 1 66 146L21 146L21 126L66 126A17 17 0 0 0 83 109L83 10Z"],
  ["glyph-e2", "e", 106.0, "M103 59L83 59L83 50A20 20 0 0 0 63 30L45 30A20 20 0 0 0 25 50L25 70A20 20 0 0 0 45 90L100 90L100 110L45 110A40 40 0 0 1 5 70L5 50A40 40 0 0 1 45 10L63 10A40 40 0 0 1 103 50L103 59ZM15 50L103 50L103 68L15 68L15 50Z"],
  ["glyph-a2", "a", 110.0, "M45 10L63 10A40 40 0 0 1 103 50L103 70A40 40 0 0 1 63 110L45 110A40 40 0 0 1 5 70L5 50A40 40 0 0 1 45 10ZM45 30A20 20 0 0 0 25 50L25 70A20 20 0 0 0 45 90L63 90A20 20 0 0 0 83 70L83 50A20 20 0 0 0 63 30L45 30ZM83 10L103 10L103 110L83 110L83 10Z"],
  ["glyph-r", "r", 68.0, "M8 10L28 10L28 110L8 110L8 10ZM28 75L8 75L8 50A40 40 0 0 1 48 10L68 10L68 30L48 30A20 20 0 0 0 28 50L28 75Z"],
] as const;

const TM = { w: 77.0, d: "M0 10L30 10L30 15.52L0 15.52L0 10ZM12 10L18 10L18 42L12 42L12 10ZM35 10L41 10L41 42L35 42L35 10ZM69 10L75 10L75 42L69 42L69 10ZM35 10L42.6 10L58.8 38.06L51.2 38.06L35 10ZM67.4 10L75 10L58.8 38.06L51.2 38.06L67.4 10Z" } as const;
const em = (units: number) => `${+(units / EM).toFixed(4)}em`;

export default function Wordmark({ tm = true, className = "", ref }: WordmarkProps) {
  return (
    <p ref={ref} className={`brand-wordmark ${className}`.trim()}>
      <span className="sr-only">spacegear</span>
      <span aria-hidden="true" className="flex items-start">
        {WORDMARK_GLYPHS.map(([id, , w, d], i) => (
          <span key={id} data-letter="" className={`fx-letter inline-block ${id}`} style={{ "--i": i } as CSSProperties}>
            <svg xmlns="http://www.w3.org/2000/svg" viewBox={`0 0 ${w} ${BAND}`} width={em(w)} height={em(BAND)} fill="currentColor" focusable="false" className="block">
              <path d={d} />
            </svg>
          </span>
        ))}
        {tm ? (
          <span className="brand-tm inline-block">
            <svg xmlns="http://www.w3.org/2000/svg" viewBox={`0 0 ${TM.w} ${BAND}`} width={em(TM.w)} height={em(BAND)} fill="currentColor" focusable="false" className="block">
              <path className="glyph-tm" d={TM.d} />
            </svg>
          </span>
        ) : null}
      </span>
    </p>
  );
}
